// File: src/test/java/com/bank/java8/CompactSourceTest.java
package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import static org.assertj.core.api.Assertions.assertThat;

class CompactSourceTest {

    // The logic a compact source file's instance main() would run.
    int reconcile(List<Integer> amounts) {
        return amounts.stream().mapToInt(Integer::intValue).sum();
    }

    @Test
    void reconcileSumsAmounts() {
        assertThat(reconcile(List.of(50000, 25000, 10000))).isEqualTo(85000);
    }
}
